ALTER TABLE public.campaigns ADD COLUMN IF NOT EXISTS poster jsonb;
CREATE POLICY "Own poster files select" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'posters' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Own poster files insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'posters' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Own poster files update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'posters' AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK (bucket_id = 'posters' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Own poster files delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'posters' AND (storage.foldername(name))[1] = auth.uid()::text);